// Package golden loads the parity data dumped from the Swift implementation
// (windows/testdata/golden, regenerated by windows/parity/regen-golden.sh) and the model
// files, for tests only.
//
// Models are read from Resources/Models at the repository root — the single source of
// truth — never from a copy, and a missing file fails the test instead of skipping it.
package golden

import (
	"encoding/json"
	"os"
	"path/filepath"
	"strconv"
	"strings"
	"testing"

	"tilqos/internal/core"
	"tilqos/internal/modelsrc"
)

// ModuleRoot is the windows/ directory (the one holding go.mod).
func ModuleRoot(t testing.TB) string {
	t.Helper()
	dir, err := os.Getwd()
	if err != nil {
		t.Fatalf("getwd: %v", err)
	}
	for {
		if data, err := os.ReadFile(filepath.Join(dir, "go.mod")); err == nil &&
			isThisModule(data) {
			return dir
		}
		parent := filepath.Dir(dir)
		if parent == dir {
			t.Fatalf("cannot find the tilqos module root above the test directory")
		}
		dir = parent
	}
}

// isThisModule checks a go.mod's module line, whatever its line endings (a Windows
// checkout with core.autocrlf turns them into CRLF).
func isThisModule(goMod []byte) bool {
	line, _, _ := strings.Cut(string(goMod), "\n")
	return strings.TrimSpace(line) == "module tilqos"
}

// RepoRoot is the repository root, which holds Resources/Models.
func RepoRoot(t testing.TB) string {
	return filepath.Dir(ModuleRoot(t))
}

// ModelDir is Resources/Models.
func ModelDir(t testing.TB) string {
	return modelsrc.Dir(RepoRoot(t))
}

// ModelFile reads one model file from its source of truth (see modelsrc.Read), failing the
// test if it is missing.
func ModelFile(t testing.TB, name string) []byte {
	t.Helper()
	data, _, err := modelsrc.Read(RepoRoot(t), name, "")
	if err != nil {
		t.Fatalf("model file missing: %v", err)
	}
	return data
}

// ModelFiles reads every model file, failing the test if any is missing.
func ModelFiles(t testing.TB) map[string][]byte {
	t.Helper()
	files := map[string][]byte{}
	for _, name := range core.ModelFileNames {
		files[name] = ModelFile(t, name)
	}
	return files
}

// Models decodes the models from Resources/Models.
func Models(t testing.TB) *core.Models {
	t.Helper()
	models, err := core.LoadModels(ModelFiles(t))
	if err != nil {
		t.Fatalf("loading models: %v", err)
	}
	return models
}

// File is the envelope every golden file uses: a header of strings plus records.
type File[T any] struct {
	Header  map[string]string
	Records []T
}

// Load reads windows/testdata/golden/<name> into a File.
func Load[T any](t testing.TB, name string) File[T] {
	t.Helper()
	path := filepath.Join(ModuleRoot(t), "testdata", "golden", name)
	data, err := os.ReadFile(path)
	if err != nil {
		t.Fatalf("golden file missing: %s (%v) — regenerate with windows/parity/regen-golden.sh", path, err)
	}
	var raw map[string]json.RawMessage
	if err := json.Unmarshal(data, &raw); err != nil {
		t.Fatalf("%s: %v", name, err)
	}
	file := File[T]{Header: map[string]string{}}
	for key, value := range raw {
		if key == "records" {
			if err := json.Unmarshal(value, &file.Records); err != nil {
				t.Fatalf("%s records: %v", name, err)
			}
			continue
		}
		var text string
		if err := json.Unmarshal(value, &text); err != nil {
			t.Fatalf("%s header %s: %v", name, key, err)
		}
		file.Header[key] = text
	}
	if len(file.Records) == 0 {
		t.Fatalf("%s has no records", name)
	}
	return file
}

// F parses a double dumped as Swift's description ("3.5", "inf", "-inf", "nan").
func F(t testing.TB, text string) float64 {
	t.Helper()
	value, err := strconv.ParseFloat(text, 64)
	if err != nil {
		t.Fatalf("bad double %q: %v", text, err)
	}
	return value
}

// LayoutRecord is one macOS layout from tables.json.
type LayoutRecord struct {
	Short   string    `json:"short"`
	ID      string    `json:"id"`
	Name    string    `json:"name"`
	Lang    *string   `json:"lang"`
	Forward []*string `json:"forward"`
	// Word is producesWordCharacter for every forward entry, as 0 and 1.
	Word    string           `json:"word"`
	Reverse map[string][]int `json:"reverse"`
}

// Tables rebuilds the macOS ABC, Russian and Kazakh tables the Swift dump used, keyed by
// short name ("abc", "ru", "kk"), plus a resolver by source ID.
func Tables(t testing.TB) (map[string]*core.KeyMapTable, core.Resolver, []LayoutRecord) {
	t.Helper()
	file := Load[LayoutRecord](t, "tables.json")
	keyCount, err := strconv.Atoi(file.Header["keyCodeCount"])
	if err != nil {
		t.Fatalf("tables.json keyCodeCount: %v", err)
	}
	keypad := map[uint16]bool{}
	for _, code := range strings.Split(file.Header["keypad"], ",") {
		value, err := strconv.Atoi(code)
		if err != nil {
			t.Fatalf("tables.json keypad: %v", err)
		}
		keypad[uint16(value)] = true
	}
	byShort := map[string]*core.KeyMapTable{}
	byID := map[string]*core.KeyMapTable{}
	for _, record := range file.Records {
		forward := make([]string, len(record.Forward))
		for i, entry := range record.Forward {
			if entry != nil {
				forward[i] = *entry
			}
		}
		lang := core.LangNone
		if record.Lang != nil {
			lang = core.LangFromCode(*record.Lang)
		}
		table := core.NewKeyMapTable(record.ID, record.Name, lang, keyCount, forward, nil, keypad)
		byShort[record.Short] = table
		byID[record.ID] = table
	}
	for _, short := range []string{"abc", "ru", "kk"} {
		if byShort[short] == nil {
			t.Fatalf("tables.json lacks the %s layout", short)
		}
	}
	return byShort, func(id string) *core.KeyMapTable { return byID[id] }, file.Records
}

// Segment is one typing segment of a golden session.
type Segment struct {
	Text   string `json:"text"`
	On     string `json:"on"`
	Active string `json:"active"`
}

// Record replays the Swift DetectorTests session helper: the keys someone would press to
// get Text on layout On, recorded as if Active had been selected. False when On cannot
// type the text.
func Record(tables map[string]*core.KeyMapTable, segments []Segment) ([]core.RecordedStroke, bool) {
	var recorded []core.RecordedStroke
	clock := 0.0
	for _, segment := range segments {
		strokes, ok := tables[segment.On].Strokes(segment.Text)
		if !ok {
			return nil, false
		}
		for _, stroke := range strokes {
			clock += 0.05
			recorded = append(recorded, core.RecordedStroke{
				Stroke: stroke, Time: clock, LayoutID: tables[segment.Active].SourceID,
			})
		}
	}
	return recorded, true
}
